<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\Event;use App\Models\EventPhoto;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class GalleryController extends Controller{public function index(){return Event::where('published',true)->whereHas('photos')->with('photos')->orderByDesc('starts_at')->paginate(12);}public function adminIndex(){return Event::withCount('photos')->with('photos')->orderByDesc('starts_at')->paginate(30);}public function upload(Request $request,Event $event){$request->validate(['photos'=>'required|array|min:1|max:30','photos.*'=>'required|image|mimes:jpeg,jpg,png,webp|max:10240','caption'=>'nullable|string|max:250']);$start=(int)$event->photos()->max('sort_order')+1;$created=[];foreach($request->file('photos') as $index=>$photo){$path=$photo->store("events/{$event->id}",'public');$created[]=EventPhoto::create(['event_id'=>$event->id,'path'=>$path,'original_name'=>$photo->getClientOriginalName(),'caption'=>$request->string('caption')->toString()?:null,'sort_order'=>$start+$index,'uploaded_by'=>$request->user()->id]);}return response()->json(['message'=>count($created).' photo(s) uploaded.','photos'=>$created],201);}public function update(Request $request,EventPhoto $photo){$photo->update($request->validate(['caption'=>'nullable|string|max:250','sort_order'=>'sometimes|integer|min:0']));return $photo->fresh();}public function destroy(EventPhoto $photo){Storage::disk('public')->delete($photo->path);$photo->delete();return response()->json(['message'=>'Photo deleted.']);}}
